"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[22158],{22158:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/premonitory-dream.png\\"\\n          title=\\"Premonitory Dream\\"\\n          author=\\"Keigo Higashino\\"\\n          publisher=\\"Jaein\\"\\n          publishedDate=\\"2009-03-31\\"\\n          isbn=\\"9788990982315\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nIt explains events that seem interpretable only supernaturally and mystically, such as premonitory dreams, out-of-body experiences, and poltergeists, through the scientific principles of ```Galileo```.  \\n<br>\\nBeyond simply revealing tricks, it poses the fundamental question of how superstition and science coexist and conflict in modern society.  \\n<br>\\nIt explains different mysteries and the scientific principles applied to them in five independent short stories.  \\n<br>\\nThe author seems to encourage the habit of doubting phenomena rather than blindly believing them, and thinking logically.  "}')}}]);